const GRAPHQL_NAME = /^[_A-Za-z][_0-9A-Za-z]*$/;
const SELECTOR_KINDS = ['query', 'mutation', 'type'];
export const parseGraphqlSelector = (str) => {
    const [rawKind, name, ...extra] = str.trim().split(/\s+/);
    if (!rawKind || !name || extra.length > 0)
        return undefined;
    const kind = SELECTOR_KINDS.find((kind) => kind.toUpperCase() === rawKind);
    if (!kind)
        return undefined;
    if (kind === 'type' && name.includes('.'))
        return undefined;
    if (!name.split('.').every((segment) => GRAPHQL_NAME.test(segment)))
        return undefined;
    return { kind, name };
};
